out = {"sourceLanguage": "en", "version": "1.0", "strings": {}}
for k, v in sorted(T.items()):
    if v is None:
        out["strings"][k] = {"shouldTranslate": False}
        continue
    out["strings"][k] = {"localizations": {lang: {"stringUnit": {"state": "translated", "value": val}} for lang, val in zip(("tr", "de", "es"), v)}}
p = os.path.join(os.path.dirname(__file__), "..", "DentVideo", "Resources", "Localizable.xcstrings")
json.dump(out, open(p, "w"), ensure_ascii=False, indent=2)
print("keys", len(T))
